pub fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    debug_assert_eq!(condition.len(), x.len(), "condition and x must have same length");
    debug_assert_eq!(condition.len(), y.len(), "condition and y must have same length");

    let n = condition.len();
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        result.push(if condition[i] { x[i] } else { y[i] });
    }

    result
}

